package app.kinnect.audit;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class LivePreparationAudit extends Instrumentation {
 int checks;public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}Object call(Object o,String n,Class<?>[] ts,Object...a)throws Exception{Method m=o.getClass().getDeclaredMethod(n,ts);m.setAccessible(true);return m.invoke(o,a);}View tag(View v,String value){if(value.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View r=tag(((ViewGroup)v).getChildAt(i),value);if(r!=null)return r;}return null;}void shot(Activity a,String name)throws Exception{Thread.sleep(100);try(FileOutputStream f=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,f);}}
 public void onStart(){Bundle result=new Bundle();Activity a=null;final Object[] socket={null};try{ClassLoader cl=getTargetContext().getClassLoader();Class<?> apiType=cl.loadClass("app.kinnect.live.NativeApi");Object api=apiType.getField("shared").get(null);call(api,"configure",new Class[]{String.class},"https://127.0.0.1:9");a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.LiveActivity").putExtra("host",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity live=a;Thread.sleep(200);check((Boolean)get(live,"creationEntry"),"Host entry flag");check(get(live,"rooms")==null,"Host entry must never build viewer lobby");check(tag(live.getWindow().getDecorView(),"live:preparation-modes")!=null,"Modes not present immediately while connecting");Class<?> socketType=cl.loadClass("app.kinnect.live.NativeSocket"),events=cl.loadClass("app.kinnect.live.NativeSocket$Events"),webSocket=cl.loadClass("okhttp3.WebSocket");Object listener=Proxy.newProxyInstance(cl,new Class[]{events},(p,m,v)->null);List<String> sent=Collections.synchronizedList(new ArrayList<>());Object fake=Proxy.newProxyInstance(cl,new Class[]{webSocket},(p,m,v)->{if(m.getName().equals("send")){sent.add(v[0].toString());return true;}if(m.getName().equals("close"))return true;if(m.getReturnType()==long.class)return 0L;return null;});runOnMainSync(()->{try{socket[0]=socketType.getConstructor(String.class,events).newInstance("https://127.0.0.1:9",listener);set(socket[0],"socket",fake);set(live,"socket",socket[0]);set(live,"config",new JSONObject().put("iceServers",new JSONArray()));call(live,"event",new Class[]{JSONObject.class},new JSONObject().put("type","welcome").put("id","fixture"));}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(1000);check((Boolean)get(live,"previewing"),"Camera preparation did not start");check(get(live,"rtc")!=null,"No camera preview RTC");ViewGroup modes=(ViewGroup)tag(live.getWindow().getDecorView(),"live:preparation-modes");check(modes!=null&&modes.getChildCount()==2,"Inline two mode choices");check(!(Boolean)get(live,"joined")&&!((Boolean)get(live,"joining")),"Preview must not begin broadcast");check(sent.isEmpty(),"Preview emitted room creation/signalling");shot(live,"live28-chat-preview.png");runOnMainSync(()->modes.getChildAt(1).performClick());Thread.sleep(250);check(get(live,"liveMode").equals("game"),"Inline Game selection");check(get(live,"rtc")==null,"Game preparation should release camera");check((Boolean)get(live,"previewing"),"Game preparation state");ViewGroup gameModes=(ViewGroup)tag(live.getWindow().getDecorView(),"live:preparation-modes");check(gameModes!=null&&gameModes.getChildCount()==2,"Game page lost inline mode selector");check(sent.isEmpty(),"Selecting Game automatically broadcast");shot(live,"live28-game-preview.png");runOnMainSync(()->gameModes.getChildAt(0).performClick());Thread.sleep(700);check(get(live,"liveMode").equals("chat")&&get(live,"rtc")!=null,"Cannot return to camera preparation");check(get(live,"rooms")==null,"Mode switch built viewer lobby");check(sent.isEmpty(),"Mode switch sent create/join");result.putString("result","PASS "+checks+": host intent opens preparation directly, modes shown while connecting, actual camera preview, inline Chat/Game switching and camera release; no lobby, no automatic create/join or broadcast. 320dp/font130.");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{final Activity last=a;runOnMainSync(()->{if(socket[0]!=null)try{call(socket[0],"close",new Class[]{});}catch(Exception ignored){}if(last!=null)last.finish();});}}
}
